/* Seeded map generation and puzzle rules shared by gameplay and verification. */
(function(root){
function random(seed){return()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
function shuffle(a,r){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
const names=['Willow Island','Sunstone Island','Moonmist Island'];
function makeMap(seed,island){const r=random(seed+island*9187),kinds=shuffle(['forest','camp','bridge','mountain','ruin','beacon'].flatMap(t=>[t,t,t]).concat(['marsh','marsh','cave','cave','lagoon','lagoon']),r);const nodes=kinds.map((type,i)=>({id:String.fromCharCode(65+i),type,x:22+(i%6)*11.2+(r()-.5)*2,y:23+Math.floor(i/6)*15.5+(r()-.5)*2,col:i%6,row:Math.floor(i/6)}));const camps=nodes.filter(n=>n.type==='camp');['rope','lantern','boat'].forEach((gear,i)=>camps[i].gear=gear);const links=[];nodes.forEach((n,i)=>{if(n.col<5)links.push([n.id,nodes[i+1].id]);if(n.row<3)links.push([n.id,nodes[i+6].id]);});const parents=nodes.map((_,i)=>i);const find=i=>parents[i]===i?i:(parents[i]=find(parents[i]));const kept=[];for(const edge of shuffle(links,r)){const a=find(edge[0].charCodeAt(0)-65),b=find(edge[1].charCodeAt(0)-65);if(a!==b){parents[a]=b;kept.push(edge);}else if(r()<.55)kept.push(edge);}links.splice(0,links.length,...kept);const glyphs=shuffle(Array.from({length:9},(_,i)=>i),r);return {seed,island,name:names[island],nodes,links,glyphs};}
function neighbors(map,id){return map.links.filter(l=>l.includes(id)).map(l=>l.find(x=>x!==id));}
function get(map,id){return map.nodes.find(n=>n.id===id);}
function gearFor(type){return type==='cave'?'lantern':type==='lagoon'?'boat':type==='mountain'?'rope':null;}
function paths(map,start,length){const out=[];function visit(id,route){if(route.length===length){out.push(route);return;}for(const next of neighbors(map,id)){if(route.includes(next)||next===start)continue;visit(next,[...route,next]);}}visit(start,[]);return out;}
function verdict(map,mission,route){if(route.length!==mission.length)return {ok:false,at:0,why:`Plan exactly ${mission.length} stops before setting off.`};let current=mission.start,gear=new Set();for(let i=0;i<route.length;i++){const n=get(map,route[i]);if(!n||!neighbors(map,current).includes(n.id))return{ok:false,at:i,why:'This stop is not joined to the previous one by a dotted path.'};if(mission.sequence[i]&&n.type!==mission.sequence[i])return{ok:false,at:i,why:`Stop ${i+1} has the wrong map symbol. Read the route from left to right.`};if(n.type==='marsh')return{ok:false,at:i,why:'The marsh is protected. Find a route that avoids its symbol.'};if(mission.gear&&i===0&&n.gear!==mission.gear)return{ok:false,at:i,why:`Your first camp needs to supply a ${mission.gear}. Check the small supply symbol beside each camp.`};if(n.gear)gear.add(n.gear);const need=gearFor(n.type);if(need&&!gear.has(need))return{ok:false,at:i,why:`You need a ${need} before entering this landmark. Collect it at the matching camp.`};if(mission.turn&&i===mission.turn.at){const prev=get(map,current);if(!(mission.turn.dir==='east'?n.col>prev.col:n.row<prev.row))return{ok:false,at:i,why:`At stop ${i+1}, the clue asks you to head ${mission.turn.dir}.`};}current=n.id;}return{ok:true,gear:[...gear]};}
function landmark(map,index,r){const candidates=shuffle(map.nodes.filter(n=>['camp','forest','ruin','beacon','bridge'].includes(n.type)),r);for(const target of candidates){const refs=shuffle(map.nodes.filter(n=>n.id!==target.id&&n.type!==target.type),r);for(const a of refs){if(a.col===target.col)continue;const dir=target.col>a.col?'east':target.col<a.col?'west':target.row<a.row?'north':'south';const check=n=>dir==='east'?n.col>a.col:dir==='west'?n.col<a.col:dir==='north'?n.row<a.row:n.row>a.row;for(const b of refs){if(a.id===b.id||b.row===target.row)continue;const dir2=target.row<b.row?'north':target.row>b.row?'south':target.col<b.col?'west':'east';const check2=n=>dir2==='north'?n.row<b.row:dir2==='south'?n.row>b.row:dir2==='west'?n.col<b.col:n.col>b.col;const matches=map.nodes.filter(n=>n.type===target.type&&check(n)&&check2(n));if(matches.length!==1)continue;return{kind:'landmark',title:index?'The landmark riddle':'Read the unfamiliar key',type:target.type,refs:[{id:a.id,dir},{id:b.id,dir:dir2}],solutions:[target.id],hint:`Find the two reference markers first. ${dir} means ${dir==='east'?'right':dir==='west'?'left':dir==='north'?'above':'below'}; ${dir2} means ${dir2==='north'?'above':dir2==='south'?'below':dir2==='east'?'right':'left'}.`};}}}throw Error('No unique landmark clue');}
function neighborMission(map,r){for(const target of shuffle(map.nodes.filter(n=>['camp','forest','ruin','beacon'].includes(n.type)),r)){const adjacent=neighbors(map,target.id).map(id=>get(map,id));for(const a of adjacent){for(const b of map.nodes){if(target.type===b.type||a.id===b.id)continue;const dir=target.row<b.row?'north':target.row>b.row?'south':target.col<b.col?'west':'east';const check=n=>dir==='north'?n.row<b.row:dir==='south'?n.row>b.row:dir==='west'?n.col<b.col:n.col>b.col;const matches=map.nodes.filter(n=>n.type===target.type&&neighbors(map,n.id).includes(a.id)&&check(n));if(matches.length===1&&matches[0].id===target.id)return{kind:'landmark',title:'Read between the landmarks',type:target.type,beside:a.id,refs:[{id:b.id,dir}],solutions:[target.id],hint:'“Beside” means connected by one dotted path. Trace every path out of the named reference, then check the direction.'};}}}return landmark(map,1,r);}
function routeMission(map,index,r,relic=false){const length=relic?5+map.island:4+Math.min(index-2,2)+map.island;const pool=[];for(const camp of map.nodes.filter(n=>n.gear)){for(const start of neighbors(map,camp.id)){if(get(map,start).type==='marsh')continue;for(const route of paths(map,start,length)){if(route[0]!==camp.id)continue;const sequence=route.map(id=>get(map,id).type);const draft={kind:'route',title:relic?'The hidden relic':index===2?'Pack for the expedition':index===3?'The cartographer’s trail':'The treasure passage',start,length,gear:camp.gear,sequence,optional:relic};if(relic||index===4){const wildcard=1+Math.floor(r()*(length-2));draft.sequence=[...sequence];draft.sequence[wildcard]=null;}const safe=verdict(map,draft,route);if(!safe.ok)continue;const usesGear=route.some(id=>gearFor(get(map,id).type)===camp.gear);if(!usesGear)continue;pool.push({...draft,example:route});if(pool.length>80)break;}if(pool.length>80)break;}if(pool.length>80)break;}
if(!pool.length){/* Long routes may not exist for every supply camp; retry shorter while preserving a real gear gate. */if(length>4)return routeMission({...map,island:Math.max(0,map.island-1)},Math.max(2,index-1),r,relic&&map.island>0);throw Error('No supply route');}
const mission=pool[Math.floor(r()*pool.length)];mission.solutions=paths(map,mission.start,mission.length).filter(p=>verdict(map,mission,p).ok);mission.hint='Decode each stop before you move. Pick up the required supply at your first camp. A mountain needs rope, a cave needs a lantern, and a lagoon needs a boat.';return mission;}
function campaign(seed,island){for(let attempt=0;attempt<50;attempt++){try{const layoutSeed=seed+attempt*4099,map=makeMap(layoutSeed,island),r=random(layoutSeed+island*711+47);map.missions=[landmark(map,0,r),neighborMission(map,r),...Array.from({length:3},(_,i)=>routeMission(map,i+2,r))];map.relics=Array.from({length:3},(_,i)=>{const m=routeMission(map,4,random(layoutSeed+island*143+i*811),true);m.title=['The sun medallion','The carved compass','The explorer’s crown'][i];return m;});return map;}catch(error){if(attempt===49)throw error;}}}
const api={random,makeMap,campaign,neighbors,get,paths,verdict,gearFor,names};if(typeof module!=='undefined')module.exports=api;root.Expedition=api;
})(typeof window==='undefined'?globalThis:window);

